//! Checks the Rust features, encoding and scoring against vectors generated by the Python reference
//! (`python tools/make_golden.py`).

use echo_rs::features::{self, FEATURE_NAMES};
use echo_rs::model::Model;
use serde::Deserialize;
use shakmaty::fen::Fen;
use shakmaty::san::SanPlus;
use shakmaty::uci::UciMove;
use shakmaty::{CastlingMode, Chess, Position};

#[derive(Deserialize)]
struct Case {
    fen: String,
    book_key: String,
    active: Vec<usize>,
    moves: Vec<String>,
    san: Vec<String>,
    features: Vec<Vec<f64>>,
    move_index: Vec<usize>,
    logits: Vec<f64>,
    v1_logits: Vec<f64>,
    scores: Vec<f64>,
}

#[derive(Deserialize)]
struct Golden {
    feature_names: Vec<String>,
    cases: Vec<Case>,
}

#[test]
fn rust_matches_python_reference() {
    let dir = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/data");
    let golden: Golden =
        serde_json::from_str(&std::fs::read_to_string(format!("{dir}/golden.json")).unwrap()).unwrap();
    let model = Model::load(&format!("{dir}/golden.echo")).unwrap();
    assert_eq!(golden.feature_names, FEATURE_NAMES.to_vec());

    let mut checked = 0;
    for case in &golden.cases {
        let pos: Chess = case.fen.parse::<Fen>().unwrap().into_position(CastlingMode::Standard).unwrap();
        assert_eq!(features::book_key(&pos), case.book_key, "book key for {}", case.fen);

        let mut active = features::encode(&pos);
        active.sort();
        assert_eq!(active, case.active, "encoding for {}", case.fen);

        let legal = pos.legal_moves();
        assert_eq!(legal.len(), case.moves.len(), "legal move count for {}", case.fen);

        let rust_moves: Vec<_> = case
            .moves
            .iter()
            .map(|uci| {
                let parsed: UciMove = uci.parse().unwrap();
                parsed.to_move(&pos).unwrap_or_else(|_| panic!("{uci} should be legal in {}", case.fen))
            })
            .collect();
        let logits = model.logits(&pos, &rust_moves);
        let scores = model.scores(&pos, &rust_moves);

        for (i, m) in rust_moves.iter().enumerate() {
            let ctx = format!("{} in {}", case.moves[i], case.fen);
            let f = features::features(&pos, m);
            for (k, v) in f.iter().enumerate() {
                assert!((v - case.features[i][k]).abs() < 1e-9, "feature {} for {ctx}", FEATURE_NAMES[k]);
            }
            assert_eq!(features::move_index(&pos, m), case.move_index[i], "move index for {ctx}");
            assert!((logits[i] - case.logits[i]).abs() < 1e-6, "logit for {ctx}: {} vs {}", logits[i], case.logits[i]);
            assert!((scores[i] - case.scores[i]).abs() < 1e-6, "score for {ctx}");
            assert_eq!(SanPlus::from_move(pos.clone(), m).to_string(), case.san[i], "SAN for {ctx}");
            checked += 1;
        }
    }
    assert!(checked > 500, "expected hundreds of golden moves, checked {checked}");
}

/// A v1 file has no promotion pieces. Loading it must not change any score: the migrated model must reproduce the
/// logits Python computes for the same legacy weights (`v1_logits`) on every golden move, under-promotions included.
#[test]
fn v1_model_migrates_without_changing_scores() {
    let dir = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/data");
    let golden: Golden =
        serde_json::from_str(&std::fs::read_to_string(format!("{dir}/golden.json")).unwrap()).unwrap();
    let v1 = Model::load(&format!("{dir}/golden_v1.echo")).unwrap();
    assert_eq!(v1.migrated_from, Some(1));
    assert_eq!(Model::load(&format!("{dir}/golden.echo")).unwrap().migrated_from, None);

    let (mut checked, mut underpromotions) = (0, 0);
    for case in &golden.cases {
        let pos: Chess = case.fen.parse::<Fen>().unwrap().into_position(CastlingMode::Standard).unwrap();
        let moves: Vec<_> =
            case.moves.iter().map(|u| u.parse::<UciMove>().unwrap().to_move(&pos).unwrap()).collect();
        let logits = v1.logits(&pos, &moves);
        for (i, uci) in case.moves.iter().enumerate() {
            assert!((logits[i] - case.v1_logits[i]).abs() < 1e-6, "{uci} in {}", case.fen);
            checked += 1;
            underpromotions += (uci.len() == 5 && !uci.ends_with('q')) as usize;
        }
    }
    assert!(checked > 500 && underpromotions >= 12, "checked {checked} moves, {underpromotions} under-promotions");
}

#[derive(Deserialize)]
struct PySummary {
    n: u64,
    observed_rate: f64,
    expected_rate: f64,
    z: f64,
    z_halves: [f64; 2],
    verdict: String,
}

/// The behavior measurements Rust reads from the profile must equal what Python computes from the same tally:
/// counts, rates, z scores (whole and halves) and the plain-language verdict.
#[test]
fn behavior_dimensions_match_python() {
    use echo_rs::model::DIMENSIONS;
    let dir = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/data");
    let raw: serde_json::Value =
        serde_json::from_str(&std::fs::read_to_string(format!("{dir}/golden.json")).unwrap()).unwrap();
    let expected: std::collections::HashMap<String, PySummary> =
        serde_json::from_value(raw["dimensions"].clone()).unwrap();

    let model = Model::load(&format!("{dir}/golden.echo")).unwrap();
    let (games, rows) = model.behavior().expect("the golden model has behavior measurements");
    assert_eq!((games, rows.len()), (12, DIMENSIONS.len()));
    let mut verdicts = std::collections::HashSet::new();
    for b in &rows {
        let py = &expected[b.name];
        assert_eq!(b.n, py.n, "{}", b.name);
        assert!((b.observed_rate - py.observed_rate).abs() < 1e-9, "{} observed", b.name);
        assert!((b.expected_rate - py.expected_rate).abs() < 1e-9, "{} expected", b.name);
        assert!((b.z - py.z).abs() < 1e-9, "{} z", b.name);
        for h in 0..2 {
            assert!((b.z_halves[h] - py.z_halves[h]).abs() < 1e-9, "{} half {h}", b.name);
        }
        assert_eq!(b.verdict, py.verdict, "{}", b.name);
        verdicts.insert(b.verdict.clone());
    }
    assert!(verdicts.len() >= 2, "the fixture should exercise more than one verdict: {verdicts:?}");
}

/// A model without the block (older profiles, the legacy v1 fixture) loads and simply has no behavior.
#[test]
fn models_without_dimensions_still_load() {
    let dir = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/data");
    // golden_v1.echo carries the same metadata, so strip it by loading a copy with the block renamed
    let mut bytes = std::fs::read(format!("{dir}/golden_v1.echo")).unwrap();
    let key = b"\"dimensions\"";
    let at = bytes.windows(key.len()).position(|w| w == key).expect("fixture has the block");
    bytes[at + 1..at + 1 + 10].copy_from_slice(b"xxxxxxxxxx"); // same length: the header stays valid JSON
    let m = Model::from_bytes(&bytes).unwrap();
    assert!(m.behavior().is_none());
}
